// The photo note on Porch & Party engine pieces (porch-and-party brain, 24 Nov 2026, her words: "You
// can make a small note on each photo that some may be touched up using ai or generated by ai. But
// make it small and not in the way"). Proves: one wording (brand.ts PHOTO_NOTE); the note is on every
// frame of every reel format and every slide of a 1- and a 10-picture carousel, drawn by the real
// component tree (Remotion's timing stubbed so a chosen frame renders in node); a brand with no note
// gets none; the layout is small, legible at phone size, inside the platforms' safe area and below all
// text; it reads on a white photo and a black one; a font that fails to load stops the render; and the
// fresh reviewer is told the new labels and to fail a missing or in-the-way note.
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { BRANDS, NOTE_PILL_ALPHA, PHOTO_NOTE, SAFE, SIZES, photoNoteLayout, textBottom, type Brand, type SizeId } from "../../engine/src/brand";
import { FORMATS, type FormatId } from "../../engine/src/library";
import type { Plan, PlanPiece } from "../../engine/src/plan";
import { brief, checklist } from "../../engine/src/review-brief";

// ------------------------------------------------------------------ a node stand-in for Remotion's timing

const stage = vi.hoisted(() => ({ frame: 0, config: { width: 1080, height: 1920, fps: 30, durationInFrames: 300, props: {} as Record<string, unknown> }, fontLoad: "pending" as "pending" | "fail" }));

vi.mock("../../engine/node_modules/remotion", async (importOriginal) => {
  const real = (await importOriginal()) as Record<string, unknown>;
  // @ts-expect-error the engine's own React (no types at the root; one React for the engine's tree)
  const React = (await import("../../engine/node_modules/react")).default;
  const Offset = React.createContext(0);
  const Sequence = ({ from = 0, durationInFrames = Infinity, children }: { from?: number; durationInFrames?: number; children?: unknown }) => {
    const start = React.useContext(Offset) + from;
    if (stage.frame < start || stage.frame >= start + durationInFrames) return null;
    return React.createElement(Offset.Provider, { value: start }, children);
  };
  return {
    ...real,
    Sequence,
    useCurrentFrame: () => stage.frame - React.useContext(Offset),
    useVideoConfig: () => stage.config,
    Img: ({ src, style }: { src: string; style?: object }) => React.createElement("img", { src, style }),
    Audio: () => null,
    staticFile: (s: string) => `/${s}`,
    delayRender: () => 1,
    continueRender: vi.fn(),
    cancelRender: vi.fn(),
  };
});

class FakeFontFace {
  load() {
    return stage.fontLoad === "fail" ? Promise.reject(new Error("font file missing")) : new Promise(() => {});
  }
}

async function engine() {
  vi.stubGlobal("FontFace", FakeFontFace);
  vi.stubGlobal("document", { fonts: { add: () => {} } });
  // @ts-expect-error the engine's own React (see the mock)
  const React = (await import("../../engine/node_modules/react")).default;
  // @ts-expect-error the engine's own react-dom
  const { renderToStaticMarkup } = await import("../../engine/node_modules/react-dom/server");
  // @ts-expect-error .tsx in the engine's own build (the root has no jsx setting)
  const formats = await import("../../engine/src/formats");
  const brand = await import("../../engine/src/brand"); // the copy formats.tsx reads after resetModules
  const remotionPath = "../../engine/node_modules/remotion"; // a runtime path: the root typecheck runs before CI installs engine/
  const remotion = (await import(/* @vite-ignore */ remotionPath)) as unknown as { cancelRender: ReturnType<typeof vi.fn>; continueRender: ReturnType<typeof vi.fn> };
  return { React, renderToStaticMarkup, formats, remotion, brand };
}

type Props = { brand: string; format: FormatId; size: SizeId; bpm: number; music: null; pics: { src: string; w: number; h: number; label?: string }[]; hook: string; lines: string[]; count: number; spots: { fx: number; fy: number; label: string }[] };
const pics = (n: number) => Array.from({ length: n }, (_, i) => ({ src: `in/p${i}.jpg`, w: 1200, h: 1600, label: i % 2 ? `Label ${i}` : undefined }));
function propsFor(format: Props["format"], brand = "pnp"): Props {
  const f = FORMATS.find((x) => x.id === format)!;
  const n = format === "this-or-that" ? 2 : f.pics[1] > 6 ? 4 : f.pics[1];
  return {
    brand,
    format,
    size: f.kind === "carousel" ? "feed" : "reel",
    bpm: 100,
    music: null,
    pics: pics(Math.max(f.pics[0], n)),
    hook: "Hook words",
    lines: Array.from({ length: Math.max(f.lines[0], Math.min(f.lines[1], 3)) }, (_, i) => `Line ${i}`),
    count: 7,
    spots: [{ fx: 0.3, fy: 0.3, label: "Spot one" }, { fx: 0.6, fy: 0.6, label: "Spot two" }, { fx: 0.5, fy: 0.4, label: "Spot three" }],
  };
}
const count = (html: string, s: string) => html.split(s).length - 1;

describe("the note's wording", () => {
  it("is one constant, and Porch & Party carries it", () => {
    expect(PHOTO_NOTE).toBe("Some photos are touched up or made with AI");
    expect(BRANDS.pnp.photoNote).toBe(PHOTO_NOTE);
  });
});

describe("drawn on every frame and every slide (the real component tree)", () => {
  beforeEach(() => {
    vi.resetModules();
    stage.fontLoad = "pending";
  });
  afterEach(() => vi.unstubAllGlobals());

  it("every reel format, at its first frame, through its body, on its end card and its last frame", async () => {
    const { React, renderToStaticMarkup, formats } = await engine();
    for (const f of FORMATS.filter((x) => x.kind === "reel")) {
      const p = propsFor(f.id);
      const total = formats.durationFrames(p);
      for (const size of ["reel", "feed", "pin"] as const) {
        stage.config = { ...stage.config, ...SIZES[size], durationInFrames: total, props: { ...p, size } };
        for (const frame of [0, Math.floor(total / 3), Math.floor((2 * total) / 3), total - 1]) {
          stage.frame = frame;
          const html = renderToStaticMarkup(React.createElement(formats.Piece, { ...p, size }));
          expect(count(html, PHOTO_NOTE), `${f.id} ${size} frame ${frame}`).toBe(1);
        }
      }
    }
  });

  it.each([1, 10])("every slide of a %i-picture carousel: cover, each picture, the closing slide", async (n) => {
    const { React, renderToStaticMarkup, formats } = await engine();
    const p = { ...propsFor("carousel"), pics: pics(n) };
    const slides = formats.carouselSlides(p);
    expect(slides).toBe(n + 2);
    stage.frame = 0;
    stage.config = { ...stage.config, ...SIZES.feed, durationInFrames: 1, props: p };
    for (let slide = 0; slide < slides; slide++) {
      const html = renderToStaticMarkup(React.createElement(formats.Piece, { ...p, slide }));
      expect(count(html, PHOTO_NOTE), `slide ${slide + 1} of ${slides}`).toBe(1);
      // the cover's wordmark and Swipe pills are lifted above the note, never under it
      if (slide === 0) expect(count(html, `bottom:${SIZES.feed.height - photoNoteLayout(BRANDS.pnp, SIZES.feed, "slide")!.textBottom}px`)).toBe(2);
    }
  });

  it("a brand with no note gets none, and its text keeps the platforms' safe bottom", async () => {
    const { React, renderToStaticMarkup, formats, brand } = await engine();
    const BRANDS = brand.BRANDS;
    BRANDS.plain = { ...BRANDS.pnp, id: "plain", photoNote: undefined };
    try {
      for (const id of ["pov", "carousel"] as const) {
        const p = propsFor(id, "plain");
        stage.frame = 0;
        stage.config = { ...stage.config, ...SIZES[p.size], props: p };
        const html = renderToStaticMarkup(React.createElement(formats.Piece, { ...p, slide: 0 }));
        expect(html).toContain("Hook words");
        expect(html).not.toContain(PHOTO_NOTE);
      }
      expect(photoNoteLayout(BRANDS.plain, SIZES.reel, "reel")).toBeNull();
      expect(textBottom(BRANDS.plain, SIZES.reel)).toBe(SIZES.reel.height * (1 - SAFE.bottom));
    } finally {
      delete BRANDS.plain;
    }
  });

  it("a brand font that fails to load stops the render (never a post in a fallback font)", async () => {
    stage.fontLoad = "fail";
    const { remotion } = await engine();
    await new Promise((r) => setTimeout(r, 0));
    expect(remotion.cancelRender).toHaveBeenCalledTimes(1);
    expect(remotion.cancelRender.mock.calls[0][0]).toBeInstanceOf(Error);
    expect(remotion.continueRender).not.toHaveBeenCalled();
  });
});

describe("the layout: small, legible, in the safe area, below every word", () => {
  const pnp = BRANDS.pnp;
  const PHONE_PT = [320, 390];
  // a generous width for the one line (Figtree 600 averages well under 0.6 em a character)
  const widest = (fontSize: number) => PHOTO_NOTE.length * 0.6 * fontSize + 1.2 * fontSize;

  for (const size of ["reel", "story", "feed", "pin"] as const) {
    it(`a reel at ${size} size: bottom-left of the safe area, about 3% high, never under ~10 pt on a 390 pt phone`, () => {
      const { width, height } = SIZES[size];
      const l = photoNoteLayout(pnp, SIZES[size], "reel")!;
      expect(l.align).toBe("left");
      expect(l.box.left).toBeCloseTo(width * SAFE.left);
      expect(l.box.left + l.box.width).toBeLessThanOrEqual(width * (1 - SAFE.right) + 0.5);
      expect(l.box.top + l.box.height).toBeLessThanOrEqual(height * (1 - SAFE.bottom) + 0.5); // above the caption block
      expect(l.box.top).toBeGreaterThan(height * SAFE.top);
      expect(l.box.height / height).toBeGreaterThanOrEqual(0.025);
      expect(l.box.height / height).toBeLessThanOrEqual(0.0375); // 3% target, hard fail 25% outside
      expect((l.fontSize * PHONE_PT[1]) / width).toBeGreaterThanOrEqual(10);
      expect((l.fontSize * PHONE_PT[0]) / width).toBeGreaterThanOrEqual(8);
      expect(widest(l.fontSize)).toBeLessThanOrEqual(l.box.width);
      // every word on screen ends above it (formats place text from useSafe().bottom = textBottom)
      expect(textBottom(pnp, SIZES[size])).toBe(l.textBottom);
      expect(l.textBottom).toBeLessThan(l.box.top);
    });
  }

  it("a carousel slide: bottom-right corner, under the cover's Swipe row and every picture label", () => {
    const { width, height } = SIZES.feed;
    const l = photoNoteLayout(pnp, SIZES.feed, "slide")!;
    expect(l.align).toBe("right");
    expect(l.box.left + l.box.width).toBeCloseTo(width - 56);
    expect(l.box.top + l.box.height).toBeLessThanOrEqual(height);
    expect(l.box.height / height).toBeLessThanOrEqual(0.0375);
    expect((l.fontSize * 390) / width).toBeGreaterThanOrEqual(10);
    expect(widest(l.fontSize)).toBeLessThanOrEqual(l.box.width);
    // a two-line picture label (formats.tsx: top 66% of the slide, 48 px Figtree, 1.15 lines, 16 px padding)
    const labelBottom = height * 0.66 + 2 * 48 * 1.15 + 2 * 16;
    expect(labelBottom).toBeLessThan(l.textBottom);
    // the cover's bottom row is lifted to sit above it
    expect(l.textBottom).toBeLessThan(l.box.top);
    expect(height - l.textBottom).toBeGreaterThan(52);
  });

  // WCAG contrast of the cotton words on the plum pill, laid over the lightest and darkest photo.
  const lum = (rgb: number[]) => {
    const c = rgb.map((v) => v / 255).map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
    return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
  };
  const hex = (h: string) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
  const contrast = (a: number[], b: number[]) => {
    const [x, y] = [lum(a), lum(b)].sort((m, n) => n - m);
    return (x + 0.05) / (y + 0.05);
  };
  it.each([
    ["a very light photo", [255, 255, 255]],
    ["a very dark photo", [0, 0, 0]],
    ["a mid-grey photo", [128, 128, 128]],
  ])("reads on %s (contrast 4.5:1 or better)", (_, photo) => {
    const pill = hex(pnp.colors.ink).map((v, i) => v * NOTE_PILL_ALPHA + photo[i] * (1 - NOTE_PILL_ALPHA));
    expect(contrast(hex(pnp.colors.ground), pill)).toBeGreaterThanOrEqual(4.5);
  });
});

describe("the fresh reviewer is told the new rule", () => {
  const piece: PlanPiece = { id: "p", format: "carousel", at: "2026-12-01 18:00", platforms: ["instagram"], hook: "Hook", pics: [{ src: "real:a.jpg" }, { src: "gen:b.png" }], captions: { instagram: "x" } };
  const plan = (brand: string): Plan => ({ studio: "s", brand, tz: "America/Chicago", window: [17, 21], cta: "x", pieces: [piece] });

  it("labels each picture: REAL may be touched up and is our real setup; an AI scene is what we can set up", () => {
    const b = brief(plan("pnp"), piece, "/out/p", ["slide-1.jpg"]);
    expect(b).toContain("1. REAL (our own job; may be touched up; call it our real setup)");
    expect(b).toContain("2. AI SCENE (what we can set up for you, never our job)");
  });
  it("fails a frame or slide without the note, and a note that is big or in the way (a P&P piece)", () => {
    const b = brief(plan("pnp"), piece, "/out/p", ["slide-1.jpg"]);
    expect(b).toContain(`"${PHOTO_NOTE}"`);
    expect(b).toMatch(/without it is a FAIL/);
    expect(b).toMatch(/big, hard to read, or in the way[^.]*is a FAIL/);
    expect(b).toMatch(/"our real setup" over an AI scene are a FAIL/);
    expect(b).toMatch(/no AI tells/);
  });
  it("asks for no note on a brand that has none", () => {
    BRANDS.plain = { ...BRANDS.pnp, photoNote: undefined } as Brand;
    try {
      expect(brief(plan("plain"), piece, "/out/p", ["slide-1.jpg"])).not.toContain(PHOTO_NOTE);
      expect(checklist(undefined)).not.toMatch(/small note/);
    } finally {
      delete BRANDS.plain;
    }
  });
});
